@namespace sv_7bf4710a133d4178bb3fd2d7b1881cd8.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" value="@FullName" @onchange="e => FullName = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" value="@Email" @onchange="e => Email = (string?)e.Value ?? string.Empty" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" value="@Phone" @onchange="e => Phone = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" rows="2" value="@Address" @onchange="e => Address = (string?)e.Value ?? string.Empty"></textarea>
    </div>

    <div class="step-actions">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private string? EmailError;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            IsValidating = false;

            if (!isValid)
            {
                EmailError = "Email address is not valid.";
                return;
            }
        }

        await OnNext.InvokeAsync((FullName, Email, Phone, Address));
    }
}

@namespace sv_7bf4710a133d4178bb3fd2d7b1881cd8.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

