{"file_text": "@page "/apply"
@using sv_7bf4710a133d4178bb3fd2d7b1881cd8.Components.Pages.Apply
@using sv_7bf4710a133d4178bb3fd2d7b1881cd8.Models
@using sv_7bf4710a133d4178bb3fd2d7b1881cd8.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                        WorkEntries="@workEntries" References="@references" CoverLetter="@coverLetter"
                        IsSubmitted="@isSubmitted" ApplicationId="@applicationId"
                        IsSubmitting="@isSubmitting" ErrorMessage="@submitError"
                        OnSubmit="HandleSubmit" OnBack="GoBack" OnEditStep="GoToStep" />
            break;
    }
</div>

@code {
    private int currentStep;
    private int highestCompletedStep = -1;

    // Step 1 state
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = string.Empty;

    // Submission state
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submitError;

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        AdvanceStep();
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        AdvanceStep();
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        AdvanceStep();
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        AdvanceStep();
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var workHistory = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)
            ).ToList());

            var refs = references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
            ).ToList();

            var application = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                workHistory,
                refs,
                coverLetter
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void AdvanceStep()
    {
        if (currentStep > highestCompletedStep)
            highestCompletedStep = currentStep;
        currentStep++;
    }

    private void GoBack() => currentStep--;

    private void GoToStep(int step)
    {
        if (step <= highestCompletedStep)
            currentStep = step;
    }
}
